concepts.example_code:
try:
    print(10 / 0)
except ZeroDivisionError:
    print("0으로 나눌 수 없어요")

try:
    print(int("abc"))
except ValueError:
    print("숫자로 변환할 수 없어요")

hints:
try:
    print(10 / 0)
except ZeroDivisionError:
    print("0으로 나눌 수 없어요")

try:
    print(int("abc"))
except ValueError:
    print("숫자로 변환할 수 없어요")

nums = [1, 2, 3]
try:
    print(nums[10])
except IndexError:
    print("범위를 벗어났어요")

values = ["10", "abc", "20"]
for v in values:
    try:
        print(int(v))
    except ValueError:
        print(v + "는 숫자가 아닙니다")
